UPDATE caregiver
name = #{name}, phone = #{phone}, gender = #{gender}, age = #{age}, skills = #{skills}, area = #{area}, status = #{status}, can_carry_device = #{canCarryDevice}, avatar = #{avatar}, bio = #{bio}, experience_years = #{experienceYears}, service_time = #{serviceTime},
WHERE id = #{id}

UPDATE caregiver
rating = #{rating}, rating_count = #{ratingCount},
WHERE id = #{id}

UPDATE caregiver SET current_order_count = current_order_count + 1,
                     total_order_count = total_order_count + 1
WHERE id = #{id}
